const $=(s,e=document)=>e.querySelector(s); const root=$('#root');
let schema=null, values={}, result=null, whatIf=null;
const H={healthy:'Saludable',at_risk:'En riesgo',critical:'Crítico',attention:'Atención',insufficient_data:'Datos insuficientes'};
const S={successful:'Exitoso',challenged:'Con desviaciones',critical:'Crítico',incomplete:'Incompleto'};
const pct=v=>v==null?'—':`${(Number(v)*100).toFixed(1)} %`; const num=(v,d=2)=>v==null?'—':Number(v).toLocaleString('es-CO',{maximumFractionDigits:d}); const money=v=>v==null?'—':Number(v).toLocaleString('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function field(spec,val,prefix='main'){
 const id=`${prefix}-${spec.name}`; const display=spec.format==='percent'?`${Math.round(Number(val??spec.reference)*100)} %`:spec.name==='planned_budget'?money(val):val??'';
 if(spec.type==='select') return `<label class="field"><span>${esc(spec.label)}</span><select data-field="${spec.name}" data-prefix="${prefix}" id="${id}">${spec.options.map(o=>`<option value="${o}" ${o===val?'selected':''}>${esc(o.replaceAll('_',' '))}</option>`).join('')}</select><small>${esc(spec.description)}</small></label>`;
 if(spec.type==='range') return `<label class="field rangeField"><div class="fieldHead"><span>${esc(spec.label)}</span><b id="${id}-display">${esc(display)}</b></div><input data-field="${spec.name}" data-prefix="${prefix}" id="${id}" type="range" min="${spec.min}" max="${spec.max}" step="${spec.step}" value="${val??spec.reference}"><small>${esc(spec.description)}</small></label>`;
 return `<label class="field"><span>${esc(spec.label)}</span><input data-field="${spec.name}" data-prefix="${prefix}" id="${id}" type="number" min="${spec.min}" max="${spec.max}" step="${spec.step}" value="${val??''}"><small>${esc(spec.description)}</small></label>`;
}
function probabilityBars(probs){if(!probs)return'';return `<div class="probBars">${Object.entries(probs).map(([k,v])=>`<div><div class="barHead"><span>${esc(H[k]||S[k]||k)}</span><b>${pct(v)}</b></div><div class="bar"><i style="width:${Math.max(0,Math.min(100,v*100))}%"></i></div></div>`).join('')}</div>`}
function resultHtml(){if(!result)return `<div class="emptyState"><div class="pulseOrb"></div><h3>Listo para analizar</h3><p>Modifica las variables o selecciona un proyecto de ejemplo. La inferencia se ejecutará en el backend con el modelo cargado.</p></div>`;
 const p=result.prediction,h=p.fused_health||p.health,tone=h==='healthy'?'good':h==='critical'?'bad':'warn';
 return `<div class="resultsWrap"><div class="heroResult"><div><span class="eyebrow">SALUD DEL PROYECTO</span><h1 class="${tone}">${esc(H[h]||h)}</h1><p>Riesgo fusionado: <b>${pct(p.fused_risk_score)}</b></p></div><div class="scoreRing ${tone}"><span>${p.fused_risk_score!=null?Math.round(p.fused_risk_score*100):'—'}</span><small>riesgo</small></div></div><div class="metricGrid"><article><span>Retraso estimado</span><strong>${num(p.delay_days,1)} días</strong><small>Predicción ML</small></article><article><span>Sobrecosto estimado</span><strong>${pct(p.cost_overrun_ratio)}</strong><small>Predicción ML</small></article><article><span>Estado final</span><strong>${esc(S[p.final_status]||p.final_status)}</strong><small>Predicción ML</small></article><article><span>Team Health</span><strong>${p.team_health?.score==null?'—':pct(p.team_health.score)}</strong><small>${esc(H[p.team_health?.level]||p.team_health?.level)}</small></article></div><div class="splitBox"><div><h3>Probabilidad Health</h3>${probabilityBars(p.health_probabilities)}</div><div><h3>Calidad de entrada</h3><p class="${p.input_quality?.complete?'goodText':'warnText'}">${p.input_quality?.complete?'✓ Todas las features entrenadas presentes':`⚠ ${p.input_quality?.missing_count} feature(s) faltante(s)`}</p>${p.input_quality?.missing_count?`<small>${esc(p.input_quality.missing_trained_features.join(', '))}</small>`:''}</div></div></div>`}
function driversHtml(){if(!result)return'';const ds=result.drivers||[];return `<section class="panel"><span class="eyebrow">EXPLICABILIDAD</span><h2>¿Qué está influyendo?</h2>${ds.length?`<div class="driverList">${ds.map(d=>`<div class="driver"><div><b>${esc(d.label)}</b><small>${d.direction==='increases_risk'?'Aumenta riesgo':'Reduce riesgo'} · referencia ${esc(d.reference)}</small></div><span class="impact ${d.direction==='increases_risk'?'bad':'good'}">${d.risk_impact>0?'+':''}${(d.risk_impact*100).toFixed(1)} pp</span></div>`).join('')}</div>`:'<p class="muted">No se detectaron impactos locales relevantes.</p>'}</section>`}
function recHtml(){if(!result)return'';const d=result.recommendations||{};return `<section class="panel"><div class="panelTitle"><div><span class="eyebrow">ACCIONES</span><h2>Recomendaciones</h2></div><span class="badge">${esc(d.engine)}</span></div>${d.reasons?.length?`<h3>Señales observadas</h3><ul>${d.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<h3>Acciones sugeridas</h3><ul>${(d.actions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="fineprint">${esc(d.disclaimer)}</p></section>`}
function deltaHtml(){if(!whatIf)return'';const d=whatIf.delta,b=whatIf.baseline.prediction,s=whatIf.scenario.prediction;return `<section class="panel delta"><span class="eyebrow">COMPARACIÓN</span><h2>Impacto del escenario</h2><div class="deltaGrid"><div><span>Health</span><b>${esc(H[b.fused_health||b.health])} → ${esc(H[s.fused_health||s.health])}</b></div><div><span>Riesgo</span><b class="${d.risk_score<=0?'goodText':'badText'}">${d.risk_score>0?'+':''}${pct(d.risk_score)}</b></div><div><span>Retraso</span><b class="${d.delay_days<=0?'goodText':'badText'}">${d.delay_days>0?'+':''}${num(d.delay_days,1)} días</b></div><div><span>Sobrecosto</span><b class="${d.cost_overrun_ratio<=0?'goodText':'badText'}">${d.cost_overrun_ratio>0?'+':''}${pct(d.cost_overrun_ratio)}</b></div></div></section>`}
function render(){
 const groups=[...new Set(schema.fields.map(f=>f.group))]; const demo=schema.model.mode==='synthetic_demo';
 root.innerHTML=`<header class="topbar"><div class="brand"><div class="mark">P</div><div><strong>PRUNIN AI Core</strong><span>Live Playground</span></div></div><div class="topmeta"><span class="badge ${demo?'warning':'success'}">${demo?'MODELO DEMO SINTÉTICO':'MODELO ACADÉMICO'}</span><span class="mono">${esc(schema.model.version)}</span><span class="liveDot">● LIVE</span></div></header><main>${demo?'<div class="notice"><b>Modo demostración:</b> el backend ejecuta modelos entrenados con datos sintéticos de smoke test. Cuando exista <code>artifacts/0.9.0-academic</code>, la aplicación lo seleccionará automáticamente.</div>':''}<div id="error"></div><section class="intro"><div><span class="eyebrow">PREDICCIÓN DE RIESGO DE PROYECTOS</span><h1>Prueba el modelo. Cambia los datos. Comprueba la respuesta.</h1><p>Health, estado final, retraso, sobrecosto y salud operativa del equipo ejecutados en vivo.</p></div><div class="legend"><span><i class="dot observed"></i>Dato observado</span><span><i class="dot derived"></i>Variable derivada</span><span><i class="dot predicted"></i>Predicción ML</span></div></section><div class="twoCol"><section class="panel inputPanel"><div class="panelTitle"><div><span class="eyebrow">ENTRADA</span><h2>Datos del proyecto</h2></div><div class="presetRow"><button class="mini good" data-preset="healthy">Saludable</button><button class="mini warn" data-preset="at_risk">En riesgo</button><button class="mini bad" data-preset="critical">Crítico</button></div></div>${groups.map(g=>`<details ${g==='Ejecución'||g==='Equipo'?'open':''}><summary>${esc(g)}</summary><div class="gridFields">${schema.fields.filter(f=>f.group===g).map(f=>field(f,values[f.name])).join('')}</div></details>`).join('')}<button id="analyze" class="primary">Analizar proyecto</button></section><section class="panel resultPanel"><span class="eyebrow">RESULTADO</span><div id="results">${resultHtml()}</div></section></div><div id="post">${result?`<div class="twoCol lower">${driversHtml()}${recHtml()}</div><section class="panel whatif"><span class="eyebrow">SIMULACIÓN</span><h2>¿Qué pasa si…?</h2><p class="muted">Parte del escenario actual, modifica acciones operativas y vuelve a ejecutar el mismo modelo.</p><div class="gridFields compact">${schema.fields.filter(f=>['spi','cpi','team_utilization','team_capacity_ratio','average_productivity','defect_rate','rework_ratio','scope_growth_ratio','dependency_delay_days','normalized_risk_exposure','governance_health_score'].includes(f.name)).map(f=>field(f,values[f.name],'what')).join('')}</div><button id="simulate" class="secondary">Simular escenario</button></section>${deltaHtml()}`:''}</div><div class="twoCol lower"><section class="panel csvPanel"><span class="eyebrow">PRUEBA PÚBLICA</span><h2>Cargar CSV</h2><p class="muted">Procesa hasta 100 filas. Cada fila se valida antes de inferencia.</p><label class="fileBox"><input id="csvFile" hidden type="file" accept=".csv,text/csv"><b id="csvName">Seleccionar archivo CSV</b><small>Máx. 5 MB</small></label><div class="buttonRow"><a class="linkButton" href="/api/csv-template">Descargar plantilla</a><button id="csvRun" class="secondary">Analizar CSV</button></div><div id="csvResults"></div></section><section class="panel tech"><button id="techToggle" class="techToggle"><span><span class="eyebrow">EVIDENCIA TÉCNICA</span><b>Detalles de inferencia</b></span><span>+</span></button><div id="techBody" class="techBody" hidden><div class="shareBox"><div><span class="eyebrow">COMPARTIR DEMO</span><b>Escanea y prueba desde otro dispositivo</b><small>El QR usa la URL actual del navegador.</small></div><img id="qrImg" alt="QR de la demo" src="/api/qr?url=${encodeURIComponent(schema.public_url||location.href)}"></div><div class="techGrid"><div><span>Modelo</span><b>${esc(schema.model.version)}</b></div><div><span>Modo</span><b>${esc(schema.model.mode)}</b></div><div><span>Ejecución</span><b>LIVE</b></div><div><span>Tiempo</span><b>${result?result.inference_ms:'—'} ms</b></div><div><span>Prediction ID</span><b class="mono tiny">${result?esc(result.prediction_id):'—'}</b></div></div>${result?`<button id="downloadJson" class="linkButton">Descargar resultado JSON</button><pre>${esc(JSON.stringify(result,null,2))}</pre>`:''}</div></section></div><footer><b>PRUNIN AI Core</b><span>Proyecto académico · Inferencia trazable · Sin resultados hardcodeados</span></footer></main>`;
 bind();
}
function bind(){
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{values={...schema.presets[b.dataset.preset]};result=null;whatIf=null;render()});
 document.querySelectorAll('[data-field][data-prefix="main"]').forEach(el=>el.oninput=()=>{const s=schema.fields.find(x=>x.name===el.dataset.field);values[el.dataset.field]=s.type==='select'?el.value:Number(el.value);const d=$(`#${el.id}-display`);if(d)d.textContent=s.format==='percent'?`${Math.round(Number(el.value)*100)} %`:el.value});
 $('#analyze').onclick=analyze; const sim=$('#simulate'); if(sim)sim.onclick=simulate;
 const file=$('#csvFile'); if(file)file.onchange=()=>{$('#csvName').textContent=file.files?.[0]?.name||'Seleccionar archivo CSV'}; const cr=$('#csvRun'); if(cr)cr.onclick=runCsv;
 const tt=$('#techToggle'); if(tt)tt.onclick=()=>{const body=$('#techBody');body.hidden=!body.hidden;tt.lastElementChild.textContent=body.hidden?'+':'−'}; const dj=$('#downloadJson'); if(dj)dj.onclick=()=>{const blob=new Blob([JSON.stringify(result,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`prunin-${result.prediction_id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
}
async function analyze(){const b=$('#analyze');b.disabled=true;b.textContent='Analizando…';try{const r=await fetch('/api/predict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const j=await r.json();if(!r.ok)throw Error(j.detail||'Error de inferencia');result=j;whatIf=null;render()}catch(e){$('#error').innerHTML=`<div class="errorBox">${esc(e.message)}</div>`;b.disabled=false;b.textContent='Analizar proyecto'}}
async function simulate(){const scenario={...values};document.querySelectorAll('[data-field][data-prefix="what"]').forEach(el=>{const s=schema.fields.find(x=>x.name===el.dataset.field);scenario[el.dataset.field]=s.type==='select'?el.value:Number(el.value)});const b=$('#simulate');b.disabled=true;b.textContent='Simulando…';try{const r=await fetch('/api/what-if',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseline:values,scenario})});const j=await r.json();if(!r.ok)throw Error(j.detail||'Error what-if');whatIf=j;render()}catch(e){alert(e.message);b.disabled=false;b.textContent='Simular escenario'}}
async function runCsv(){const f=$('#csvFile').files?.[0];if(!f)return alert('Selecciona un CSV.');const fd=new FormData();fd.append('file',f);const b=$('#csvRun');b.disabled=true;b.textContent='Procesando…';try{const r=await fetch('/api/predict-csv',{method:'POST',body:fd});const j=await r.json();if(!r.ok)throw Error(j.detail||'Error CSV');$('#csvResults').innerHTML=`<div class="tableWrap"><table><thead><tr><th>Fila</th><th>Health</th><th>Delay</th><th>Cost</th><th>Estado</th></tr></thead><tbody>${j.rows.map(x=>x.error?`<tr><td>${x.row_number}</td><td colspan="4" class="badText">${esc(x.error)}</td></tr>`:`<tr><td>${x.row_number}</td><td>${esc(H[x.prediction.prediction.fused_health||x.prediction.prediction.health])}</td><td>${num(x.prediction.prediction.delay_days,1)} d</td><td>${pct(x.prediction.prediction.cost_overrun_ratio)}</td><td>${esc(S[x.prediction.prediction.final_status])}</td></tr>`).join('')}</tbody></table></div>`}catch(e){alert(e.message)}finally{b.disabled=false;b.textContent='Analizar CSV'}}
fetch('/api/schema').then(r=>{if(!r.ok)throw Error('No se pudo cargar el esquema');return r.json()}).then(j=>{schema=j;values={...j.presets.at_risk};render()}).catch(e=>root.innerHTML=`<div class="boot"><div class="mark big">P</div><h2>PRUNIN AI Core</h2><p>${esc(e.message)}</p></div>`);
